/** Cross-check the actual browser MONKEYS series and its OLS engine against
 * independent statsmodels estimates generated by tools/alpha_audit.py.
 * This test has no UI implications and skips locally when derived data is absent.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { buildView } from '../src/model.ts';
import { defaults } from '../src/state.ts';
import { fitModel, type ModelId } from '../src/engine/factors.ts';
import type { CovType } from '../src/engine/ols.ts';
import type { Market, Manifest, MonkeysFile, StrategiesFile } from '../src/data/types.ts';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const derived = join(root, 'public', 'data');
const auditFile = join(root, 'alpha-audit.json');

function close(actual: number, expected: number, name: string) {
  assert.ok(Number.isFinite(actual) && Number.isFinite(expected), `${name}: non-finite`);
  assert.ok(Math.abs(actual - expected) <= 2e-8 * Math.max(1, Math.abs(expected)),
    `${name}: browser=${actual}, statsmodels=${expected}`);
}

test('published MONKEYS factor results match independent statsmodels', {
  skip: !existsSync(auditFile) || !existsSync(join(derived, 'manifest.json')),
}, () => {
  const manifest = JSON.parse(readFileSync(join(derived, 'manifest.json'), 'utf8')) as Manifest;
  const market = JSON.parse(readFileSync(join(derived, 'market.json'), 'utf8')) as Market;
  const state = defaults(manifest);
  const key = `L${state.window}_${state.cov}_cap${state.cap}`;
  const monkeyKey = `L${state.window}_${state.freq}_k${state.k}_s${state.seed}_${state.mkMode}`;
  const strategies = JSON.parse(readFileSync(join(derived, 'strategies', `${key}.json`), 'utf8')) as StrategiesFile;
  const monkeys = JSON.parse(readFileSync(join(derived, 'monkeys', `${monkeyKey}.json`), 'utf8')) as MonkeysFile;
  const audit = JSON.parse(readFileSync(auditFile, 'utf8'));
  const view = buildView(strategies, market, monkeys, state);
  assert.ok(view.series.has('MONKEYS'));
  const returns = view.series.get('MONKEYS')!.r;
  for (const cov of ['classical', 'HC3', 'HAC'] as CovType[]) {
    for (const [model, reference] of [
      ['FF5MOM', 'A_original'],
      ['FF5MOMBAB', 'C_plus_BAB'],
    ] as [ModelId, string][]) {
      const f = fitModel(view.months, returns,
        { months: market.months, rf: market.rf, factors: market.factors }, model, cov);
      assert.equal(f.ok, true, `${model} ${cov}`);
      if (!f.ok) continue;
      const comparison = audit.results.methods[cov][reference];
      assert.equal(f.result.n, comparison.n, `${model} ${cov} months`);
      close(12 * f.result.beta[0], comparison.alpha_pa, `${model} ${cov} alpha`);
      close(12 * f.result.se[0], comparison.se_pa, `${model} ${cov} standard error`);
      close(f.result.stat[0], comparison.stat, `${model} ${cov} t/z`);
      close(f.result.pvalue[0], comparison.p, `${model} ${cov} p-value`);
      close(f.result.r2adj, comparison.r2adj, `${model} ${cov} R2adj`);
    }
  }
});
